function u(n){if(!n)return"";const r=String(n).trim();if(r.includes("ص")||r.includes("م")||r.includes("AM")||r.includes("PM"))return r;const c=r.match(/^(\d{1,2}):(\d{2})/);if(!c)return r;let t=parseInt(c[1],10);const f=c[2],i=t>=12?"م":"ص";return t===0?t=12:t>12&&(t=t-12),`${String(t).padStart(2,"0")}:${f} ${i}`}function e(n,r){return!n&&!r?"":r?n?`${u(n)} — ${u(r)}`:u(r):u(n)}export{e as f};
